class Vehiculo:
    def __init__(self, marca, modelo, año):
        self.marca = marca
        self.modelo = modelo
        self.año = año

    def info(self):
        print(f"{self.marca} {self.modelo} ({self.año})", end="")

class Coche(Vehiculo):
    def __init__(self, marca, modelo, año, num_puertas):
        super().__init__(marca, modelo, año)
        self.num_puertas = num_puertas

    def info(self):
        super().info()
        print(f" - {self.num_puertas} puertas")

class Motocicleta(Vehiculo):
    def __init__(self, marca, modelo, año, tipo):
        super().__init__(marca, modelo, año)
        self.tipo = tipo

    def info(self):
        super().info()
        print(f" - moto {self.tipo}")

